def ss(sta,idx,period):
 q=S[(S.station==sta)&(S['index']==idx)&(S.period==period)]
 return q.iloc[0] if len(q) else None

def context(txt):
 sta=[s for s in ['London','Fergus','Harrow'] if re.search(r'\b'+s+r'\b',txt,re.I)] or ['London','Fergus','Harrow'];inds=[k for k in ALL if re.search(r'(?<![A-Za-z0-9])'+re.escape(k)+r'(?![A-Za-z0-9])',txt,re.I)];return sta,inds

def pooledcontext(txt):
 sta,inds=context(txt);ans=[]
 for st in sta:
  for k in inds[:6]:
   q=S[(S.station==st)&(S['index']==k)]
   if len(q):ans.append(st+' '+k+' H/P/N/F='+','.join(fmt(ss(st,k,p)['median']) for p in PER))
 return '; '.join(ans)

records=[]
def put(cid,printed,value,verdict,ev,reason=''):
 records.append(dict(claim=cid,printed=printed,recomputed=value,verdict=verdict,evidence=ev,reason=reason))

def default(cid,txt):
 sta,inds=context(txt);value='No complete independent value for this claim. '
 if inds:value+=pooledcontext(txt)+'; '
 if any(k in txt for k in ['SPEI','SPI']):reason='SPI/SPEI were not independently fitted from daily inputs; post-seal monthly calculations use supplied Climpact outputs.';ev='conditional_monthly_all_models.csv'
 elif re.search(r'crop|insurance|actuar|nutrient|runoff|snowpack|groundwater|Mennonite|pollination|erosion|soil frost|greenhouse|citat|et al\.',txt,re.I):reason='The daily meteorological pack alone does not identify this causal, agricultural, hydrological, actuarial or cited-literature claim. No independent crop, discharge, snow, groundwater, nutrient, economic or cited-source dataset was supplied for the particular assertion.';ev='pass1_execution.json'
 elif any(k in txt.lower() for k in ['homogen','changepoint','break','50 to 16','18 or 19']):reason='Independent RHtests detection, iterative pruning and quantile matching were not implemented. Inputs are present; this is unperformed executor work, not a missing-input claim or a consequence of R alone.';ev='supplied_homogenisation_daily_effect.csv'
 elif 'a priori' in txt or 'before any' in txt:reason='Group counts and implemented ratings can be checked; temporal pre-specification requires a dated analysis plan or version history not supplied.';ev='conditional_confidence_recomputed.csv'
 elif 'p-value' in txt or 'pass count' in txt or 'Wilcoxon' in txt:reason='Full blind daily-to-homogenised-indices Test 1 was not completed; conditional Python recalculation from supplied annual inputs is available and is not promoted to end-to-end confirmation.';ev='conditional_test1_pvalues.csv'
 elif any(k not in CORE for k in inds):reason='Independent EHF/ECF, compound-index or in-base percentile bootstrap computation is missing; fixed-percentile results are a sensitivity only.';ev='percentile_primary_selected_cells.csv'
